<?php require 'config.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['add_cake'])){$image='';if(!empty($_FILES['image']['name'])){$dir=__DIR__.'/uploads';if(!is_dir($dir))mkdir($dir,0755,true);$ext=strtolower(pathinfo($_FILES['image']['name'],PATHINFO_EXTENSION));if(!in_array($ext,['jpg','jpeg','png','webp']))exit('Only JPG, PNG or WEBP images allowed');$image='uploads/'.bin2hex(random_bytes(8)).'.'.$ext;move_uploaded_file($_FILES['image']['tmp_name'],__DIR__.'/'.$image);}$s=$pdo->prepare('INSERT INTO cakes(name,category_id,subcategory_id,flavor,occasion,description,price,image,stock) VALUES(?,?,?,?,?,?,?,?,?)');$s->execute([trim($_POST['name']),(int)$_POST['category_id']?:1,$_POST['subcategory_id']?:null,trim($_POST['flavor']),trim($_POST['occasion']),trim($_POST['description']),(float)$_POST['price'],$image,(int)$_POST['stock']]);header('Location: admin.php');exit;}if(isset($_GET['status'],$_GET['order'])){$pdo->prepare('UPDATE orders SET status=? WHERE id=?')->execute([$_GET['status'],(int)$_GET['order']]);header('Location: admin.php');exit;}if(isset($_GET['toggle'])){$pdo->prepare('UPDATE cakes SET active=1-active WHERE id=?')->execute([(int)$_GET['toggle']]);header('Location: admin.php');exit;}$cats=$pdo->query('SELECT * FROM categories')->fetchAll();$cakes=$pdo->query('SELECT c.*,ca.name category FROM cakes c JOIN categories ca ON ca.id=c.category_id ORDER BY c.id DESC')->fetchAll();$orders=$pdo->query('SELECT o.*,u.name customer FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.id DESC')->fetchAll();?>
<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.css"></head><body><div class="wrap"><div class="card"><h1>Admin panel</h1><h2>Post cake / Manage products</h2><form method="post" enctype="multipart/form-data" class="grid"><input type="hidden" name="add_cake" value="1"><input name="name" placeholder="Cake name" required><select name="category_id"><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=h($c['name'])?></option><?php endforeach;?></select><input name="subcategory_id" type="number" placeholder="Subcategory ID (optional)"><input name="flavor" placeholder="Flavor" required><input name="occasion" placeholder="Occasion"><input name="price" type="number" step=".01" placeholder="Price" required><input name="stock" type="number" min="0" placeholder="Stock" required><input name="image" type="file" accept=".jpg,.jpeg,.png,.webp"><textarea name="description" placeholder="Description" required></textarea><button>Add cake</button></form><h2>Product inventory</h2><table><tr><th>Cake</th><th>Category</th><th>Price</th><th>Stock</th><th>Visibility</th><th>Action</th></tr><?php foreach($cakes as $c):?><tr><td><?=h($c['name'])?></td><td><?=h($c['category'])?></td><td><?=money($c['price'])?></td><td><?=h($c['stock'])?></td><td><?=$c['active']?'Active':'Hidden'?></td><td><a href="admin.php?toggle=<?=$c['id']?>">Toggle</a></td></tr><?php endforeach;?></table><h2>Manage orders and delivery status</h2><table><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th><th>Update</th></tr><?php foreach($orders as $o):?><tr><td>#<?=$o['id']?></td><td><?=h($o['customer'])?></td><td><?=money($o['total'])?></td><td><?=h($o['status'])?></td><td><?php foreach(['Order confirmed','Preparing','Out for delivery','Delivered','Cancelled'] as $st):?><a href="admin.php?order=<?=$o['id']?>&status=<?=urlencode($st)?>"><?=h($st)?></a><br><?php endforeach;?></td></tr><?php endforeach;?></table><p><a href="dashboard.php">Back to dashboard</a></p></div></div></body></html>